  str_n26_1_name_desc = "/",
  str_n26_2_name_desc = "ดังที่ Zhong Xu เพื่อนเก่าของตระกูล Lin บอกคุณมากขึ้น คุณค่อยๆ ปะติดปะต่อความประทับใจที่เป็นรูปธรรมมากขึ้นเกี่ยวกับตระกูล Lin ในใจของคุณ",
  str_n26_3_name_desc = "พายุพัดถล่ม คุณตัดสินใจไปที่ดาดฟ้าเพื่อช่วย Yuebai และ Liqing ท่ามกลางความโกลาหล คุณรู้สึกถึงสิ่งมีชีวิตที่ผิดปกติในทะเล...",
  str_n26_4_name_desc = "Shadowind ได้รับความเสียหายอย่างหนักและแทบจะไม่สามารถแล่นต่อไปได้ ในสถานการณ์ที่เลวร้ายเช่นนี้ ดูเหมือนว่าเธอทำได้เพียงภาวนาให้สวรรค์มีเมตตา...",
  str_n26_5_name_desc = "การค้นหาเข็มทิศที่สูญหายไปในส่วนลึกและการค้นหาชิ้นส่วนที่จำเป็นในซากปรักหักพังนั้นเหมือนกับการพยายามงมเข็มในมหาสมุทร... คุณจะทำสำเร็จหรือไม่?",
  str_n26_6_name_desc = "บางครั้งสัตว์ก็มีสัญชาตญาณที่เฉียบแหลมกว่าพวกออโรเรียน และสามารถค้นหาสิ่งที่ไม่สามารถมองเห็นด้วยตาเปล่าได้ง่ายๆ",
  str_n26_7_name_desc = "บางครั้งสัตว์รู้เรื่องความร่วมมือมากกว่าพวกออโรเรียน และสามารถถ่ายทอดข้อมูลไปยังเพื่อนที่พวกมันไว้ใจได้อย่างถูกต้อง",
  str_n26_8_name_desc = "/",
  str_n26_9_name_desc = "คุณต้องอดทนไม่ว่าจะบรรลุผลหรือไม่ก็ตาม",
  str_n26_10_name_desc = "ความกลัวความหิวเป็นสัญชาตญาณเบื้องต้น ทุกคนต้องทำในสิ่งที่ทำได้เพื่อบรรเทาความไม่สบายใจ",
  str_n26_11_name_desc = "คุณต้องเสี่ยงเพื่อดูว่ามีความหวังจริง ๆ ที่ไหนสักแห่งในมหาสมุทรอันกว้างใหญ่หรือไม่",
  str_n26_12_name_desc = "นี่ไม่ใช่ Shadowind ที่คุณคุ้นเคย สถานที่นี้คืออะไรกันแน่?",
  str_n26_13_name_desc = "เข็มทิศอยู่ที่นั่น คุณแทบจะสัมผัสมันได้",
  str_n26_14_name_desc = "สัตว์บางครั้งมีความแค้นมากกว่า Aurorians ทุกสิ่งที่พวกเขาประสบจะได้รับคืนเป็นสิบเท่า",
  str_n26_15_name_desc = "/",
  str_n26_1_name_desc_long = "Twin Pavilions Bay มีชีวิตชีวาด้วยบรรยากาศของเทศกาลฤดูใบไม้ผลิ เทศกาลดั้งเดิมจากหลงโจว คุณและผู้โดยสารคนอื่น ๆ จาก Shadowind อยู่ที่นี่มาระยะหนึ่งแล้ว และในที่สุดคุณก็เตรียมตัวออกเดินทาง อย่างไรก็ตาม ในขณะที่ Shadowind กำลังจะออกเรือ Tweety ก็พบคุณอีกครั้งและมอบจดหมายให้คุณเพื่อส่งข้ามมหาสมุทร ตามคำขอของ Tweety คุณตัดสินใจไปที่ทวีป Longzhou ในนามของเธอ โดยเริ่มดำเนินการกับ Shadowind",
  str_n26_2_name_desc_long = "Zhong Xu และ Liqing เพื่อนใหม่ของคุณจาก Twin Pavilions Bay ดูเหมือนจะมีความเกี่ยวข้องกับเรือที่คุณโดยสารอยู่ ที่โต๊ะอาหารค่ำ Zhong Xu เล่าถึงประสบการณ์ของเขาที่ล่องลอยไปที่ Astra เมื่อครึ่งปีก่อน เมื่อเขาและ Liqing พบกับความโชคร้ายบนเรือ Shadowind ผลจากเหตุการณ์นั้น ไม่เพียงแต่หัวหน้ากิลด์ Lin เท่านั้นที่ได้รับบาดเจ็บสาหัส อุปกรณ์นำทางอันน่าภาคภูมิใจของตระกูล Lin อย่าง The Compass ก็จมลงสู่ทะเลพร้อมกับเรือลำเก่า",
  str_n26_3_name_desc_long = "ความปั่นป่วนอย่างฉับพลันทำให้แขกแต่ละคนตื่นขึ้นทีละคนขณะที่พวกเขาพักผ่อนในห้องโดยสาร เกิดพายุเข้า ลม ฟ้าร้อง และฝนกระหน่ำอยู่รอบตัวคุณ แทนที่จะติดตามทีมกู้ภัย คุณมุ่งหน้าไปที่ดาดฟ้าเรือ Yuebai นำลูกเรือไปรักษาเสถียรภาพของเรือในขณะที่ Liqing ย่อตัวลงข้างหนึ่งด้วยความกลัว เมื่อคุณใช้ความสามารถทางจิตของคุณเพื่อค้นหาสหายของคุณ ฝูงปลางูจะเริ่มจู่โจม Shadowind อย่างเมามัน",
  str_n26_4_name_desc_long = "หลังจากผ่านไปหนึ่งคืนในการต่อสู้ที่ดุเดือดระหว่างความเป็นและความตาย Shadowind ก็กลายเป็นรูพรุน และส่วนตัวถังที่สำคัญทั้งหมดก็หายไป โชคดีที่คุณและพรรคพวกของคุณยังมีชีวิตอยู่ แต่สถานการณ์เลวร้าย เสบียงจะหมดในไม่ช้า คุณต้องหาทางแล่นเรืออีกครั้ง Li Tianxian หรือที่รู้จักกันในนามนักต้มตุ๋น ได้ทำนายดวงชะตาสามแบบให้กับ Shadowind ซึ่งให้แรงบันดาลใจแก่ Yuebai",
  str_n26_5_name_desc_long = "ด้วยประสบการณ์ของ Zhong Xu บนเรือที่กำลังจม คุณตัดสินใจเดิมพันทุกอย่างในการเปิดใช้งาน Shadowind ใหม่และเริ่มค้นหาชิ้นส่วนที่คุณต้องการ ใบเรือได้รับความเสียหาย ดังนั้นจึงสามารถพายเรือด้วยมือได้เท่านั้น หากเรือแล่นไปอย่างช้าๆ ในสภาพอากาศแจ่มใส คุณอาจยังมีโอกาสเปลี่ยนชะตากรรมได้ ผู้คนบนเรือต่างสั่นคลอน แต่ Yuebai แน่วแน่กับสิ่งที่ต้องทำ ถ้าเธอต้องแสดงความกลัวใดๆ คงไม่มีใครเชื่อว่ามีร่องรอยแห่งความหวังอยู่",
  str_n26_6_name_desc_long = "ทุกคนออกเดินทางทีละคนและตัดสินใจที่จะมองหากังหันลมที่หายไป—หางของหนู—บนเรือ Shadowind ขนาดใหญ่ นอกจากนี้ Dantang ยังปรารถนาที่จะทำบางสิ่งเพื่อช่วยรักษา Shadowind แต่เธอไม่รู้อะไรเลยเกี่ยวกับหางของหนู Tianxian ปรากฏตัวพร้อมกับนกพูดได้สองตัวของเขา พวกเขาวนเวียนอยู่บนท้องฟ้าด้านบนและหาหางของหนูได้อย่างง่ายดาย",
  str_n26_7_name_desc_long = "Liqing ยืนกรานที่จะนำเรือชูชีพออกทะเลเพียงลำพังเพื่อกอบกู้ลูกรอกที่มีชื่อเล่นว่า \"หัวลิง\" แต่เขาลังเลเนื่องจากความกลัวน้ำโดยกำเนิด ด้วยความเป็นห่วง คุณจึงขึ้นเรือชูชีพและล่องลอยไปในทะเลอันเงียบสงบกับเขา Liqing รู้ชัดเจนว่าคุณสองคนกำลังจะไปที่ไหน และคุณจับหัวลิงขึ้นมาจากซากเรือได้สำเร็จ เขาบอกคุณว่าทั้งหมดนี้ต้องขอบคุณ \"เพื่อนในทะเล\" ของเขา",
  str_n26_8_name_desc_long = "ในการซ่อม Shadowind คุณเริ่มพยายามกอบกู้ชิ้นส่วนพิเศษจากเรือที่จม นั่นก็คือหูกระต่าย พวกมันถูกใช้เพื่อปิดรอยรั่วที่ด้านล่างของเรือ ซึ่งช่วยลดแรงกดดันต่อ Shadowind ได้สำเร็จ จนถึงขณะนี้ งานซ่อมแซมได้เสร็จสิ้นไปมากแล้ว ลูกเรือรวมตัวกันเพื่อเฉลิมฉลอง และทุกคนเริ่มเชื่อว่าการเดินทางที่เหลือจะประสบความสำเร็จ",
  str_n26_9_name_desc_long = "เมื่อเวลาผ่านไป การมองโลกในแง่ดีของลูกเรือก็ค่อยๆ จางหายไป ปัญหาในทางปฏิบัติเริ่มเกิดขึ้นมากขึ้นเรื่อยๆ ด้วยวัตถุดิบที่ไม่เพียงพอ ลูกเรือเริ่มป่วย และตอนนี้ พายุอีกลูกก็ขวางทาง",
  str_n26_10_name_desc_long = "เสบียงอาหารเหลือน้อย และลูกเรือไม่มีทางเลือกอื่นนอกจากใช้เวลาหาปลาให้มากขึ้น โดยไม่คาดคิด ปลาช่อนตัวหนึ่งถูกจับได้โดยบังเอิญ เหตุการณ์ที่เกือบทำให้เรือล่ม ลี่ชิงรีบบอกลูกเรือให้ปล่อยปลาช่อนเพื่อหลีกเลี่ยงหายนะครั้งใหญ่ อย่างไรก็ตาม Zhong Xu เห็นอย่างอื่น เขาพบกัปตันคนเดียวและประกาศว่าเข็มทิศอยู่ข้างหน้า",
  str_n26_11_name_desc_long = "คุณเห็นซากปรักหักพังของ Shadowind เก่าจากดาดฟ้า Yuebai กระโดดลงน้ำทันที ส่วนคุณกับ Liqing ตามหลังมาติดๆ โดยเรือ แต่ทันใดนั้นก็มีหมอกลงเหนือทะเลและมองไม่เห็นสิ่งใดท่ามกลางผ้าห่มสีขาวอันกว้างใหญ่ Yuebai เข้าร่วมกับคุณและบอกคุณว่าเธอพบเรือที่สูญหายที่ก้นมหาสมุทร ขณะที่คุณล่องลอย เรือลำใหญ่ก็ปรากฏขึ้นต่อหน้าคุณ",
  str_n26_12_name_desc_long = "คุณขึ้นเรือลำใหญ่ท่ามกลางหมอก แต่ไม่พบใครอยู่บนนั้น ดูเหมือนจะไม่ใช่ Shadowind... แต่ Liqing คนเดียวที่จำมันได้ มันคือ Shadowind เก่า เขาพาคุณไปตามหาเข็มทิศอย่างตื่นเต้น ในขณะเดียวกัน ในรายการ Shadowind ปัจจุบัน Zhong Xu บอกทุกคนเกี่ยวกับช่วงเวลาสุดท้ายของ Shadowind เก่า ขณะที่เขากำลังเล่าเรื่องราวของเขา จู่ๆ ก็มีเสียงดังขึ้น พวกเขามีเพื่อนร่วมทางแล้ว",
  str_n26_13_name_desc_long = "ขณะที่คุณค้นหา The Compass ในห้องโดยสารของ Shadowind รุ่นเก่า จู่ๆ ก็มีคนมาขังคุณไว้ในห้อง Liqing อุทานว่าแท้จริงแล้วผู้ร้ายคือ The Compass—เดิมทีเขาเป็นอสรพิษ แต่ตอนนี้กลายเป็นสัตว์ร้ายที่มีพลังมหัศจรรย์ หากคุณตามเขาไม่ทัน ความพยายามทั้งหมดของคุณจะสูญเปล่า",
  str_n26_14_name_desc_long = "Zhong Xu นำคนอื่น ๆ ขึ้นเรือลำเก่าและพบกับ The Compass ซึ่งตอนนี้เป็นสัตว์ร้ายที่มีชีวิต เขาเต็มไปด้วยความขุ่นเคืองต่อชาว Aurorian และเรือที่กักขังเขา เขาพยายามที่จะส่งคุณทั้งหมดไปยังก้นมหาสมุทร หลังจากการสู้รบที่ดุเดือด คุณเอาชนะเขาได้ แต่ความเกลียดชังของเขาทำให้ทุกคนต้องทบทวนการตัดสินใจของพวกเขาใหม่ Yuebai ปล่อยเขาลงทะเลเพื่อแก้ไขความผิดในอดีต Shadowind เริ่มต้นการเดินทางช่วงสุดท้าย และคุณออกเดินทางไป Longzhou ทันใดนั้น ปลาช่อนก็โผล่ขึ้นมาจากทะเลและแบกเรือยักษ์ไว้บนหลัง",
  str_n26_15_name_desc_long = "ในที่สุด Shadowind ก็เข้าเทียบท่าได้สำเร็จ และการผจญภัยอันเลวร้ายของคุณก็จบลงในที่สุด คุณใช้เทศกาลฤดูใบไม้ผลิกับครอบครัวหลิน จดหมายที่คุณนำมานั้นแปลก แต่ภารกิจของคุณเสร็จสมบูรณ์แล้ว ไม่กี่วันต่อมา Yuebai เชิญคุณไปดู Shadowind เพื่อเป็นสักขีพยานในการกลับมาสู่ความรุ่งโรจน์ คุณเซ็นชื่อของคุณบนเรือ เรือ Shadowind จะพามันไปมาระหว่างหลงโจวและแอสตร้า สลักชื่อของคุณในทะเลตลอดไป",
  str_n26_food_name_1 = "ปลานึ่ง",
  str_n26_food_name_2 = "ลูกงา",
  str_n26_food_name_3 = "หมูตุ๋น",
  str_n26_food_name_4 = "ลูกกุ้ง",
  str_n26_food_name_5 = "ปอเปี๊ยะ",
  str_n26_food_name_6 = "ลูกชิ้นหก",
  str_n26_food_name_7 = "ข้าวคลุก",
  str_n26_food_name_8 = "พิซซ่ามะเขือเทศ",
  str_n26_food_name_9 = "ไข่ตุ๋น",
  str_n26_food_name_10 = "นักเก็ต",
