  str_n26_food_name_12 = "สเต็กเนื้อ",
  str_n26_food_name_13 = "อุดร",
  str_n26_food_name_14 = "ข้าวผัด",
  str_n26_food_desc_1 = "ปลาหมักขิงและไวน์ปรุงอาหารแล้วนึ่งในหม้อ ซอสถั่วเหลืองถูกเติมลงไปเพื่อให้ได้รสอูมามิในปริมาณที่เหมาะสม",
  str_n26_food_desc_2 = "ขนมง่ายๆ อร่อยๆ ทำจากข้าวเหนียวสอดไส้งาดำ เหมาะสำหรับทั้งเด็กและผู้ใหญ่",
  str_n26_food_desc_3 = "หมูสับปรุงกับซีอิ๊วหรือน้ำตาลจนเป็นสีน้ำตาลสวย อ้วนแต่ไม่สะอิดสะเอียน",
  str_n26_food_desc_4 = "เกี๊ยวยัดไส้กุ้งต้มในน้ำแล้ววางในหวด เด้งดึ๋งและอร่อย แต่ละคำเต็มไปด้วยรสชาติ",
  str_n26_food_desc_5 = "ปอเปี๊ยะทอดจนเหลืองกรอบ ทำด้วยเนื้อฝอย กะหล่ำปลี เต้าหู้ และอื่นๆ ขนมกรุบกรอบที่มีรสชาติซับซ้อน",
  str_n26_food_desc_6 = "ลูกชิ้นหมูและทะเลทอดก่อนแล้วตุ๋น ซอสมีสีสดใสกลิ่นและรสชาติ",
  str_n26_food_desc_7 = "ข้าวและเครื่องปรุงต่างๆ ปรุงในหม้อจนมีชั้นข้าวกรอบที่ด้านล่าง กลิ่นเข้มข้นและไม่อาจต้านทานได้",
  str_n26_food_desc_8 = "ฐานแป้งโรยหน้าด้วยมะเขือเทศ เห็ด และอื่นๆ อบเพื่อความสมบูรณ์แบบ เหมาะสำหรับการแบ่งปัน",
  str_n26_food_desc_9 = "ตีไข่แล้วนึ่งในหม้อ ปรุงรสด้วย ซีอิ๊วขาว ต้นหอมสำหรับโรยหน้า แม้จะเรียบง่าย แต่ก็เป็นอาหารหลงโจวที่ได้รับความนิยมอย่างมาก",
  str_n26_food_desc_10 = "ไก่หั่นเต๋าชุบแป้งทอดจนเหลืองกรอบนอกนุ่มใน",
  str_n26_food_desc_11 = "เนื้อย่างในหม้อเหล็กปรุงรสด้วยซีอิ๊วหวาน เสริมด้วยเห็ด แครอท เต้าหู้ และเครื่องเคียงอื่นๆ",
  str_n26_food_desc_12 = "สเต็กเนื้อชิ้นกลางทอดในกระทะเหล็กกับเนยจนเหลืองทั้งสองด้าน เสิร์ฟพร้อมซอสพริกไทยดำ",
  str_n26_food_desc_13 = "เส้นหนาทำจากแป้ง เกลือ และน้ำ มักจะปรุงในน้ำซุป",
  str_n26_food_desc_14 = "ข้าวชุบไข่ผัดจนเหลือง สามารถใส่เห็ด ถั่วลันเตา แครอท กุ้ง และอื่นๆ เพื่อรสชาติที่เข้มข้น",
  str_n26_food_tishi_1 = "เดอะ <color=#b74b25>แป้ง</color> และ <color=#b74b25>เครื่องปรุงรส</color> อัตราส่วนส่วนควรเป็น 2:1\n<color=#b74b25>ต้องเพิ่มส่วนผสมอย่างละ 1 ส่วนเป็นอย่างน้อย</color>",
  str_n26_food_tishi_2 = "เดอะ <color=#b74b25>ผัก</color> และ <color=#b74b25>เครื่องปรุงรส</color> ส่วนควรเท่ากัน\n<color=#b74b25>ต้องเพิ่มส่วนผสมอย่างละ 1 ส่วนเป็นอย่างน้อย</color>",
  str_n26_food_tishi_3 = "จำนวน <color=#b74b25>อาหารทะเล</color> สัดส่วนควรน้อยกว่าผลรวมของส่วนผสมอีกสองอย่าง\n<color=#b74b25>ต้องเพิ่มส่วนผสมอย่างละ 1 ส่วนเป็นอย่างน้อย</color>",
  str_n26_food_tishi_4 = "จำนวน <color=#b74b25>เนื้อ</color> ส่วนควรเป็นสองเท่าของจำนวน <color=#b74b25>เครื่องปรุงรส</color> ส่วน\n<color=#b74b25>ต้องเพิ่มส่วนผสมอย่างละ 1 ส่วนเป็นอย่างน้อย</color>",
  str_n26_food_tishi_5 = "จำนวน <color=#b74b25>แป้ง</color> สัดส่วนควรมากกว่าผลรวมของส่วนผสมอีกสองอย่าง\n<color=#b74b25>ต้องเพิ่มส่วนผสมอย่างละ 1 ส่วนเป็นอย่างน้อย</color>",
