  str_n26_food_tishi_11 = "จำนวน <color=#b74b25>ข้าว</color> ส่วนควรเท่ากับผลรวมของส่วนผสมอีกสามอย่าง และส่วนที่เล็กที่สุดควรเป็น <color=#b74b25>ไข่</color>.\n<color=#b74b25>ต้องเพิ่มส่วนผสมอย่างละ 1 ส่วนเป็นอย่างน้อย</color>",
