  str_n26_food_tishi_13 = "ควรมีอีกหนึ่ง <color=#b74b25>ผัก</color> ส่วนที่มากกว่าที่มีอยู่ <color=#b74b25>เนื้อ</color> ส่วน\n<color=#b74b25>ต้องเพิ่มส่วนผสมอย่างละ 1 ส่วนเป็นอย่างน้อย</color>",
